code.css:
h1{font-size:var(--ui-size-title);font-weight:600;margin:0 0 var(--ui-space-3)}
.bar{display:flex;flex-wrap:wrap;gap:var(--ui-space-3);align-items:center;margin-bottom:var(--ui-space-2)}
label{display:flex;align-items:center;gap:var(--ui-space-2)}
button{min-height:var(--ui-target);padding:0 var(--ui-space-4);border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);background:var(--ui-surface);color:var(--ui-text);font:inherit;cursor:pointer}
button[aria-pressed="true"]{background:var(--ui-accent-soft);border-color:var(--ui-accent);font-weight:600}
button:focus-visible,input:focus-visible,canvas:focus-visible{outline:3px solid var(--ui-accent);outline-offset:2px}
input[type=color]{width:var(--ui-target);height:var(--ui-target)}
.note{color:var(--ui-text-secondary);font-size:var(--ui-size-secondary);margin:var(--ui-space-2) 0}
canvas{display:block;width:100%;height:auto;background:#fff;border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);touch-action:none;cursor:crosshair}

