const cv=document.getElementById('board');
const ctx=cv.getContext('2d');
ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);
const color=document.getElementById('color');
const size=document.getElementById('size');
const sizeOut=document.getElementById('sizeOut');
const pen=document.getElementById('pen');
const eraser=document.getElementById('eraser');
const msg=document.getElementById('msg');
let erasing=false,drawing=false,lx=0,ly=0;
function pos(e){const r=cv.getBoundingClientRect();return [(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height];}
function setMode(er){erasing=er;pen.setAttribute('aria-pressed',String(!er));eraser.setAttribute('aria-pressed',String(er));msg.textContent=er?'Eraser on. Drag to rub out.':'Pen on. Drag to draw.';}
function style(){ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=Number(size.value);ctx.strokeStyle=erasing?'#fff':color.value;ctx.fillStyle=ctx.strokeStyle;}
cv.addEventListener('pointerdown',e=>{drawing=true;cv.setPointerCapture(e.pointerId);const p=pos(e);lx=p[0];ly=p[1];style();ctx.beginPath();ctx.arc(lx,ly,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();});
cv.addEventListener('pointermove',e=>{if(!drawing)return;const p=pos(e);style();ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(p[0],p[1]);ctx.stroke();lx=p[0];ly=p[1];});
function stop(){drawing=false;}
cv.addEventListener('pointerup',stop);
cv.addEventListener('pointercancel',stop);
size.addEventListener('input',()=>{sizeOut.textContent=size.value+' px';});
pen.addEventListener('click',()=>setMode(false));
eraser.addEventListener('click',()=>setMode(true));
color.addEventListener('input',()=>setMode(false));
document.getElementById('clear').addEventListener('click',()=>{if(!confirm('Clear the whole board? This removes your drawing.'))return;ctx.fillStyle='#fff';ctx.fillRect(0,0,cv.width,cv.height);msg.textContent='Board cleared.';});

